import { Router } from 'express';
import { UserController } from './user.controller.js';
import { requireAuth, optionalAuth } from '../../middleware/authMiddleware.js';
const router = Router();
router.get('/friends/all', requireAuth, UserController.getFriends);
router.get('/friends/suggestions', requireAuth, UserController.getSuggestions);
router.get('/notifications', optionalAuth, UserController.getNotifications);
router.patch('/profile', requireAuth, UserController.updateProfile);
router.get('/:id', optionalAuth, UserController.getUserProfile);
router.post('/:id/follow', requireAuth, UserController.toggleFollow);
export const userRoutes = router;
